 static int n;static void ok(boolean b,String m){n++;if(!b)throw new AssertionError(m);}static ClassNode cls(ZipFile z,String name)throws Exception{ClassNode c=new ClassNode();var e=z.getEntry(name+".class");ok(e!=null,"class exists: "+name);new ClassReader(z.getInputStream(e).readAllBytes()).accept(c,0);return c;}
