 public static void main(String[]args)throws Exception{try(ZipFile z=new ZipFile(args[0]);ZipFile nativeJar=new ZipFile(args[1])){gate(z,nativeJar,"GunRunGate31","GunRunAnimationClient");gate(z,nativeJar,"ProneGate31","ProneTacticalAnimationClient");gate(z,nativeJar,"WallPoseGate31","TaczWallObstructionClient");var mix=cls(z,"dev/zomboidmelee/mixin/LeanPlayer31");var old=cls(nativeJar,"com/locknar/taczammocheck/tactical/mixin/PlayerRendererMixin");String wanted="render(Lnet/minecraft/client/player/AbstractClientPlayer;FFLcom/mojang/blaze3d/vertex/PoseStack;Lnet/minecraft/client/renderer/MultiBufferSource;I)V";for(var c:List.of(mix,old)){boolean found=false;for(MethodNode m:c.methods)if(m.visibleAnnotations!=null)for(var a:m.visibleAnnotations)if(a.desc.endsWith("/Inject;")&&a.values.toString().contains(wanted))found=true;ok(found,"same declared PlayerRenderer entry as supplied native mixin");}var step=cls(z,"dev/zomboidmelee/boxing/StepEvents31");ok(step.methods.get(0).desc.contains("client/event/sound/PlaySoundSourceEvent"),"actual non-streaming sound event drives footsteps");String cfg=new String(z.getInputStream(z.getEntry("zomboid_global_melee.mixins.json")).readAllBytes());ok(cfg.contains("LeanPlayer31")&&cfg.contains("WallPoseGate31")&&cfg.contains("GunRunGate31")&&cfg.contains("ProneGate31"),"all new mixins registered");System.out.println("UPLOADED_TACZ_NATIVE_POSE_OWNERSHIP_THIRD_RENDER_AND_FOOTSTEP_EVENT_CHECKS="+n);}}
